def write_samples(path, acquisition):
    fields = (
        "case",
        "round",
        "pair",
        "side",
        "wall_ms",
        "process_cpu_ms",
        "average_cores",
        "whole_process_peak_rss_bytes",
        "final_snapshot_sha256",
    )
    with path.open("w", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields)
