    identities = {}
    for side, source in roots.items():
        identity = with_measured_harness(
            build_provenance(
                source,
                [
                    Path(f"crates/calc-flow/benches/{name}.rs")
                    for name in bench_targets(source)
                ],
            ),
            output / side,
        )
        identities[side] = with_compiled_dependencies(
            identity,
            source,
            {
                name: output / side / f"build-{name}.jsonl"
                for name in bench_targets(source)
            },
            build_roots={
                target: Path(record["build_source"])
                for target, record in identity.get("measured_harnesses", {}).items()
            },
        )
    return identities


async def measure_rust(shard: dict, releases: dict, roots: dict, output: Path) -> dict:
    shared = ROOT / "target/benchmark-rust-build"
    binaries = {
        side: await build_binaries(source, output / side, shared)
        for side, source in roots.items()
    }
    provenance = _rust_provenance(roots, output)
    if set(binaries["baseline"]) - set(binaries["candidate"]):
        raise ValueError(
            "Rust benchmark targets removed; an explicit migration is required"
        )
    blocks = {side: [] for side in roots}
    errors = []
    migrations = load_migrations(ROOT)
    applied = with_harness_migrations(
        declared_migrations(provenance, migrations), provenance, migrations
    )
    stamps = stamp_dependency_migrations(
        provenance,
        _stamp_fingerprints(provenance, applied),
        load_dependency_migrations(),
    )
    for index, side in enumerate(("baseline", "candidate", "candidate", "baseline")):
        block, failures = await _rust_block(
            binaries[side],
            roots[side],
            output / f"block-{index}-{side}",
            stamps[side],
            side,
        )
        errors.extend(f"{side}/{error}" for error in failures)
        blocks[side].append(block)
        (output / "blocks.json").write_text(
            json.dumps(blocks, indent=2) + "\n", encoding="utf-8"
        )
    cases = combine_blocks(shard, _without_retired_cases(blocks, applied))
    try:
        reports = await _allocation_reports(binaries, roots, output)
        cases.extend(allocation_rows(reports))
    except Exception as error:
        errors.append(f"allocation_regression: {error}")
    return {
        "contract": CONTRACT,
        "harness_sha256": harness_sha256(),
        "provenance": provenance,
        "binary_sha256": _binary_hashes(binaries),
        "shard": shard,
        "releases": releases,
        "cases": cases,
        "errors": errors,
        "expected_case_ids": [case["id"] for case in cases],
        "workload_migrations": sorted(
            applied.values(), key=lambda entry: entry["target"]
        ),
        "dependency_migrations": applied_dependency_migrations(stamps),
    }


def _target(name: str) -> str:
    return name.split("/", 1)[0]


def _names(side_blocks: list[dict]) -> set[str]:
    return {name for block in side_blocks for name in block}


def _measured_targets(side_blocks: list[dict]) -> set[str]:
    """Targets that report at least one case in every block of one side."""
    targets = [{_target(name) for name in block} for block in side_blocks]
    return set.intersection(*targets) if targets else set()


def _retired_cases(blocks: dict, applied: dict) -> set[str]:
    removed = _names(blocks["baseline"]) - _names(blocks["candidate"])
    eligible = _measured_targets(blocks["candidate"]) & applied.keys()
    return {name for name in removed if _target(name) in eligible}


def _without_retired_cases(blocks: dict, applied: dict) -> dict:
    """Drop cases a declared migration removed from the candidate bench source.

    A migrated target's candidate inventory is authoritative once the candidate
    measured that target: a case only its baseline blocks still report was
    removed deliberately. Without a declaration it stays a missing-block error.
    """
    retired = _retired_cases(blocks, applied)
    return {
        side: [
            {name: row for name, row in block.items() if name not in retired}
            for block in values
        ]
        for side, values in blocks.items()
    }


async def _allocation_reports(binaries: dict, roots: dict, output: Path) -> dict:
    return {
        side: await allocation(
            values["allocation_regression"], roots[side], output / side, side
        )
        for side, values in binaries.items()
    }


def _binary_hashes(binaries: dict) -> dict:
    return {
        side: {
            name: hashlib.sha256(path.read_bytes()).hexdigest()
            for name, path in values.items()
        }
        for side, values in binaries.items()
    }


def _with_fingerprints(measured: dict, fingerprints: dict) -> dict:
    return {
        name: {**row, "metadata": {**row["metadata"], **fingerprints}}
        for name, row in measured.items()
    }


def _migration_marker(declared: dict | None) -> dict:
    """Mark rows accepted through one declared migration with its reference."""
    return {} if declared is None else {"workload_migration": declared["reference"]}


def _stamp_fingerprints(provenance: dict, applied: dict) -> dict:
    """Per-side, per-target fingerprint metadata for row stamping.

    Each target's rows carry its own scoped workload fingerprint, so a changed
    bench source invalidates only that target; a declared migration re-baselines
    the stamp to the candidate identity and records its reference instead.
    """
    _require_common_harness(provenance)
    candidate_scoped = provenance["candidate"]["scoped_workload_fingerprints"]
    return {
        side: {
            target: {
                "machine_fingerprint": identity["machine_fingerprint"],
                "dependency_fingerprint": target_dependency_fingerprint(
                    identity, target
                ),
                "workload_fingerprint": identity.get(
                    "measured_workload_fingerprints", {}
                ).get(
                    target, candidate_scoped[target] if target in applied else scoped
                ),
                **_migration_marker(applied.get(target)),
            }
            for target, scoped in identity["scoped_workload_fingerprints"].items()
        }
        for side, identity in provenance.items()
    }


def _require_common_harness(provenance: dict) -> None:
    baseline_identity = provenance.get("baseline", {})
    candidate_identity = provenance["candidate"]
    baseline = baseline_identity.get("measured_harnesses", {})
    candidate = candidate_identity.get("measured_harnesses", {})
    baseline_targets = baseline_identity.get("scoped_workload_fingerprints", {})
    candidate_targets = candidate_identity["scoped_workload_fingerprints"]
    shared = baseline_targets.keys() & candidate_targets.keys() & {JOIN_HARNESS_TARGET}
    for target in baseline.keys() | candidate.keys() | shared:
        if _candidate_only_harness(target, baseline_identity, candidate_identity):
            continue
        if (
            target not in baseline
            or target not in candidate
            or any(
                baseline[target][key] != candidate[target][key]
                for key in ("measured_sha256", "harness_git_sha")
            )
        ):
            raise ValueError(
                f"Rust comparison requires a common measured harness: {target}"
            )


def _candidate_only_harness(target: str, baseline: dict, candidate: dict) -> bool:
    return (
        target not in baseline.get("scoped_workload_fingerprints", {})
        and target in candidate["scoped_workload_fingerprints"]
        and target not in baseline.get("measured_harnesses", {})
    )


async def _rust_block(
    binaries: dict, source: Path, output: Path, stamps: dict, side: str
) -> tuple[dict, list[str]]:
    block, errors = {}, []
    for target, binary in binaries.items():
        if target == "allocation_regression":
            continue
        try:
            measured = await run_binary(target, binary, source, output / target, side)
            block.update(_with_fingerprints(measured, stamps[target]))
        except Exception as error:
            errors.append(f"{target}: {error}")
    return block, errors

